#!/usr/bin/env python3
"""
视频流媒体服务器 - 单文件版（HTML内嵌）
支持 HTTP Range Request 实现视频拖动进度条
Python 3.9 标准库实现，无第三方依赖
"""

import http.server
import json
import os
import urllib.parse
import base64
from functools import partial
from typing import Optional, Tuple

# 默认配置
DEFAULT_PORT = 8080
DEFAULT_VIDEO_DIR = "./videos"

# 内嵌 index.html（base64编码）
INDEX_HTML_B64 = ""

def get_index_html():
    """解码内嵌的 index.html"""
    return base64.b64decode(INDEX_HTML_B64)

def parse_filename(filename: str) -> dict:
    """
    解析文件名，提取标题和标签
    """
    name = filename
    for ext in ['.mp4', '.MP4', '.mov', '.MOV', '.avi', '.AVI']:
        if name.lower().endswith(ext.lower()):
            name = name[:-len(ext)]
            break
    
    suffixes_to_remove = ['_xWT111', '_xWT222', '_xWT333', '_kling', '_kl', '_mj', '_midjourney']
    for suffix in suffixes_to_remove:
        if name.endswith(suffix):
            name = name[:-len(suffix)]
            break
    
    if '#' in name:
        parts = name.split('#')
        title = parts[0].strip()
        tags = [tag.strip() for tag in parts[1:] if tag.strip()]
    else:
        title = name.strip()
        tags = []
    
    return {
        "title": title,
        "tags": tags,
        "raw": filename
    }


def scan_videos(video_dir: str) -> list:
    """扫描视频目录，返回视频列表"""
    videos = []
    
    if not os.path.isdir(video_dir):
        return videos
    
    for filename in os.listdir(video_dir):
        if filename.lower().endswith(('.mp4', '.MP4', '.mov', '.MOV')):
            filepath = os.path.join(video_dir, filename)
            if os.path.isfile(filepath):
                parsed = parse_filename(filename)
                videos.append({
                    "name": filename,
                    "title": parsed["title"],
                    "tags": parsed["tags"],
                    "size": os.path.getsize(filepath)
                })
    
    videos.sort(key=lambda x: x["title"])
    return videos


def get_video_path(video_dir: str, filename: str) -> Optional[str]:
    """获取视频文件的完整路径"""
    filename = urllib.parse.unquote(filename)
    filepath = os.path.join(video_dir, filename)
    
    real_path = os.path.realpath(filepath)
    real_dir = os.path.realpath(video_dir)
    
    if not real_path.startswith(real_dir + os.sep) and real_path != real_dir:
        return None
    
    if os.path.isfile(real_path):
        return real_path
    return None


class VideoStreamingHandler(http.server.BaseHTTPRequestHandler):
    """支持 Range Request 的视频流媒体处理器"""
    
    video_dir = DEFAULT_VIDEO_DIR
    
    def log_message(self, format, *args):
        print(f"[{self.log_date_time_string()}] {format % args}")
    
    def send_cors_headers(self):
        self.send_header('Access-Control-Allow-Origin', '*')
        self.send_header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS')
        self.send_header('Access-Control-Allow-Headers', 'Content-Type, Range')
    
    def do_OPTIONS(self):
        self.send_response(200)
        self.send_cors_headers()
        self.end_headers()
    
    def do_GET(self):
        path = urllib.parse.unquote(self.path)
        
        # API: 视频列表（支持 ?_t= 缓存破坏参数）
        if path == '/api/videos' or path.startswith('/api/videos?') or path == '/api/videos.json':
            self.handle_api_videos()
            return
        
        # API: 视频详情
        if path.startswith('/api/video/'):
            filename = path[11:]
            self.handle_api_video_info(filename)
            return
        
        # 视频文件
        if path.startswith('/videos/'):
            filename = path[8:]
            self.handle_video(filename)
            return
        
        # 根路径返回 index.html（从内嵌数据）
        if path == '/' or path == '/index.html':
            self.handle_index()
            return
        
        self.send_error(404, 'Not found')
    
    def handle_api_videos(self):
        videos = scan_videos(self.video_dir)
        
        all_tags = set()
        for video in videos:
            all_tags.update(video["tags"])
        
        response = {
            "videos": videos,
            "total": len(videos),
            "tags": sorted(list(all_tags))
        }
        
        json_data = json.dumps(response, ensure_ascii=False, indent=2)
        
        self.send_response(200)
        self.send_header('Content-Type', 'application/json; charset=utf-8')
        self.send_header('Content-Length', len(json_data))
        self.send_header('Cache-Control', 'no-cache, no-store')
        self.send_cors_headers()
        self.end_headers()
        self.wfile.write(json_data.encode('utf-8'))
    
    def handle_api_video_info(self, filename: str):
        filepath = get_video_path(self.video_dir, filename)
        
        if not filepath:
            self.send_error(404, 'Video not found')
            return
        
        parsed = parse_filename(filename)
        size = os.path.getsize(filepath)
        
        response = {
            "name": filename,
            "title": parsed["title"],
            "tags": parsed["tags"],
            "size": size,
            "url": f"/videos/{urllib.parse.quote(filename)}"
        }
        
        json_data = json.dumps(response, ensure_ascii=False, indent=2)
        
        self.send_response(200)
        self.send_header('Content-Type', 'application/json; charset=utf-8')
        self.send_header('Content-Length', len(json_data))
        self.send_cors_headers()
        self.end_headers()
        self.wfile.write(json_data.encode('utf-8'))
    
    def handle_video(self, filename: str):
        filepath = get_video_path(self.video_dir, filename)
        
        if not filepath:
            self.send_error(404, 'Video not found')
            return
        
        file_size = os.path.getsize(filepath)
        
        range_header = self.headers.get('Range')
        
        if range_header:
            self.handle_range_request(filepath, file_size, range_header)
        else:
            self.handle_full_file(filepath, file_size)
    
    def handle_full_file(self, filepath: str, file_size: int):
        self.send_response(200)
        self.send_header('Content-Type', 'video/mp4')
        self.send_header('Content-Length', file_size)
        self.send_header('Accept-Ranges', 'bytes')
        self.send_cors_headers()
        self.end_headers()
        
        with open(filepath, 'rb') as f:
            self.wfile.write(f.read())
    
    def handle_range_request(self, filepath: str, file_size: int, range_header: str):
        try:
            range_match = range_header.replace('bytes=', '').split('-')
            
            if len(range_match) != 2:
                raise ValueError("Invalid Range header")
            
            start = int(range_match[0]) if range_match[0] else 0
            end = int(range_match[1]) if range_match[1] else file_size - 1
            
            if start >= file_size:
                self.send_error(416, 'Range Not Satisfiable')
                return
            
            end = min(end, file_size - 1)
            length = end - start + 1
            
            self.send_response(206)
            self.send_header('Content-Type', 'video/mp4')
            self.send_header('Content-Length', length)
            self.send_header('Content-Range', f'bytes {start}-{end}/{file_size}')
            self.send_header('Accept-Ranges', 'bytes')
            self.send_cors_headers()
            self.end_headers()
            
            with open(filepath, 'rb') as f:
                f.seek(start)
                remaining = length
                chunk_size = 1024 * 1024
                
                while remaining > 0:
                    to_read = min(chunk_size, remaining)
                    data = f.read(to_read)
                    if not data:
                        break
                    self.wfile.write(data)
                    remaining -= len(data)
                    
        except (ValueError, IOError) as e:
            print(f"Range request error: {e}")
            self.send_error(400, 'Bad Request')
    
    def handle_index(self):
        """返回 index.html（从内嵌数据）"""
        content = get_index_html()
        
        self.send_response(200)
        self.send_header('Content-Type', 'text/html; charset=utf-8')
        self.send_header('Content-Length', len(content))
        self.send_header('Cache-Control', 'no-cache, no-store')
        self.send_cors_headers()
        self.end_headers()
        self.wfile.write(content)


def run_server(port: int = DEFAULT_PORT, video_dir: str = DEFAULT_VIDEO_DIR):
    if not os.path.isabs(video_dir):
        video_dir = os.path.abspath(video_dir)
    
    VideoStreamingHandler.video_dir = video_dir
    
    server_address = ('', port)
    handler = VideoStreamingHandler
    
    print(f"=" * 50)
    print(f"视频流媒体服务器（单文件版）")
    print(f"=" * 50)
    print(f"视频目录: {video_dir}")
    print(f"端口: {port}")
    print(f"访问地址: http://localhost:{port}")
    print(f"=" * 50)
    
    videos = scan_videos(video_dir)
    print(f"发现 {len(videos)} 个视频文件")
    
    if videos:
        print(f"示例: {videos[0]['title']}")
    
    print(f"=" * 50)
    print(f"按 Ctrl+C 停止服务器")
    print(f"=" * 50)
    
    httpd = http.server.HTTPServer(server_address, handler)
    httpd.serve_forever()


if __name__ == '__main__':
    import sys
    
    port = DEFAULT_PORT
    video_dir = DEFAULT_VIDEO_DIR
    
    args = sys.argv[1:]
    for i, arg in enumerate(args):
        if arg in ['-p', '--port']:
            if i + 1 < len(args):
                port = int(args[i + 1])
        elif arg in ['-d', '--dir', '--video-dir']:
            if i + 1 < len(args):
                video_dir = args[i + 1]
        elif not arg.startswith('-'):
            if os.path.isdir(arg):
                video_dir = arg
    
    if 'VIDEO_PORT' in os.environ:
        port = int(os.environ['VIDEO_PORT'])
    if 'VIDEO_DIR' in os.environ:
        video_dir = os.environ['VIDEO_DIR']
    
    run_server(port, video_dir)
